    Strings Strings::ForLocale(const std::string& tag) {
        // Android's resource fallback (ResourceLocaleCandidates ends with the default).
        const Entry* e = nullptr;
        for (const std::string& t : text::ResourceLocaleCandidates(tag)) if ((e = Lookup(t))) break;
        Strings s;
        s.stateOn = e->values[0];
        s.stateOff = e->values[1];
        s.indeterminate = e->values[2];
        s.selected = e->values[3];
        s.notSelected = e->values[4];
        s.templatePercent = e->values[5];
        s.inProgress = e->values[6];
        s.stateEmpty = e->values[7];
        s.tab = e->values[8];
        s.switchRole = e->values[9];
        s.locale = tag;
        return s;
    }

